-- ============================================================================
-- Labour & Delivery OVERALL SUMMARY (babies) - delivery details mandatory fields
-- INPUT: a table or CTE named `mahis_pivot` (output of ld/mahis_ld_pivot.sql). To use a CTE instead of a table, put this script's
-- WITH list after `WITH RECURSIVE mahis_pivot AS ( <pivot query> ),`
-- Generated by build_dqa_scripts.py from the MNH Neonatal data dictionary rules.
-- ============================================================================
SET SESSION group_concat_max_len = 1000000;

WITH baby_level AS (
    -- One row per baby: latest non-empty value of each field across all visit days
    SELECT
        p.person_id,
        SUBSTRING_INDEX(GROUP_CONCAT(p.location_id ORDER BY p.visit_date DESC), ',', 1) AS location_id,
        MIN(p.visit_date) AS first_visit_date,
        MAX(p.visit_date) AS last_visit_date,
        COUNT(DISTINCT p.visit_date) AS number_of_visits,
        DATEDIFF(MAX(p.visit_date), MIN(p.visit_date)) + 1 AS days_spanned,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sexually_transmitted_infection AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sexually_transmitted_infection,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dehydration AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dehydration,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hta AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hta,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dysmenorrhoea AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dysmenorrhoea,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cleft_lip AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cleft_lip,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.coma AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS coma,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.palpitations AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS palpitations,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.wheezing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS wheezing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cough AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cough,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nausea AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nausea,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chronic_diarrhoea_more_than_1_month AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chronic_diarrhoea_more_than_1_month,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.icterus AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS icterus,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cyanosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cyanosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dysuria AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dysuria,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prolonged_fever_over_1_mo AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prolonged_fever_over_1_mo,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oedema AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oedema,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.diabetes_mellitus_disorder_tm2 AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS diabetes_mellitus_disorder_tm2,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.heart AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS heart,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.palate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS palate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tongue AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tongue,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sacrum AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sacrum,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.uterus AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS uterus,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.neck AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS neck,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vaccines AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vaccines,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chest_pain AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chest_pain,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.convulsion AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS convulsion,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pale_conjunctiva AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pale_conjunctiva,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nasal_blockage AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nasal_blockage,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_loss AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_loss,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.parity AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS parity,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.phone_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS phone_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.contraceptive_use AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS contraceptive_use,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gravida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gravida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_test_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_test_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abnormal_vaginal_discharge AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abnormal_vaginal_discharge,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pulse_rate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pulse_rate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.wheezes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS wheezes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.facility_for_art AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS facility_for_art,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.the_woman_received_tetanus_doses_for_immunization AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS the_woman_received_tetanus_doses_for_immunization,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_tetanus_toxoid_tt_was_not_conducted AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_tetanus_toxoid_tt_was_not_conducted,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.daily_caffeine_use AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS daily_caffeine_use,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.which_medications_is_the_woman_currently_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS which_medications_is_the_woman_currently_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abortions_miscarriages AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abortions_miscarriages,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.stillbirths AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS stillbirths,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.live_births AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS live_births,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.danger_signs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS danger_signs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.livebirths AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS livebirths,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tt2date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tt2date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.congenital_abnormalities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS congenital_abnormalities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pallor AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pallor,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.discharge AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS discharge,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.symphysis_fundal_height AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS symphysis_fundal_height,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_fetuses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_fetuses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.misuse_of_drugs AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS misuse_of_drugs,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_general_condition_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_general_condition_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_at_1_minute AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_at_1_minute,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_at_5_minutes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_at_5_minutes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_k_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_k_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cord_bleeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cord_bleeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.breast_feeding_in_the_first_hour_of_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS breast_feeding_in_the_first_hour_of_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.skin_to_skin_contact_with_the_mother AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS skin_to_skin_contact_with_the_mother,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.delayed_bathing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS delayed_bathing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.delayed_cord_cutting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS delayed_cord_cutting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.outcome_of_the_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS outcome_of_the_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_pregnancy_problems AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_pregnancy_problems,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.status_of_lochia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS status_of_lochia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.episiotomy_tear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS episiotomy_tear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.postnatal_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS postnatal_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.current_weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS current_weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_condition AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_condition,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.immunisation_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS immunisation_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_bcg_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_bcg_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_polio_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_polio_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cord_care AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cord_care,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chest_in_drawing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chest_in_drawing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_a_supplementation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_a_supplementation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.discharge_status_of_woman AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS discharge_status_of_woman,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.past_pregnancies_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS past_pregnancies_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_tetanus_doses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_tetanus_doses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.protected_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS protected_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.how_many_doses_of_tdv_did_the_mother_receive AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS how_many_doses_of_tdv_did_the_mother_receive,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_of_labour_onset AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_of_labour_onset,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.time_of_labour_onset AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS time_of_labour_onset,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.date_membranes_ruptured AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS date_membranes_ruptured,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.time_membranes_ruptured AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS time_membranes_ruptured,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.state_of_cervix AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS state_of_cervix,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_at_menarche AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_at_menarche,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.excessive_thirst AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS excessive_thirst,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.shape_of_brim AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS shape_of_brim,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sacrospinous_ligaments AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sacrospinous_ligaments,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ischial_spines AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ischial_spines,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.sub_pubic_arch AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS sub_pubic_arch,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.intertuberous_diameter AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS intertuberous_diameter,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.conclusion_about_pelvis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS conclusion_about_pelvis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anticipated_course_of_labour_and_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anticipated_course_of_labour_and_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.bladder AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS bladder,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.what_is_the_reason_for_coming_to_the_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS what_is_the_reason_for_coming_to_the_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.labour_onset_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS labour_onset_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.membranes_ruptured AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS membranes_ruptured,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.has_she_had_food_in_4_hours AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS has_she_had_food_in_4_hours,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.homemade_medicines_taken AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS homemade_medicines_taken,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.who_is_being_referred AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS who_is_being_referred,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_for_referring_mother AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_for_referring_mother,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referral_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referral_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.grunting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS grunting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.length AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS length,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.neural_tube_defect_spina_bifida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS neural_tube_defect_spina_bifida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.capillary_refill AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS capillary_refill,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_at_10_minutes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_at_10_minutes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.femoral_pulses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS femoral_pulses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.has_passed_urine AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS has_passed_urine,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.eyes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS eyes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.extra_digits AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS extra_digits,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.talipes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS talipes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.suck_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS suck_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.moro_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS moro_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.health_education AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS health_education,
