        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.symmetry AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS symmetry,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vulva_inspection AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vulva_inspection,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.webbing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS webbing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_grams AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_grams,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.maternal_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS maternal_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_gynaecological_information AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_gynaecological_information,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ambiguous_genitalia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ambiguous_genitalia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.breasts_examination AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS breasts_examination,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fetal_and_neonatal_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fetal_and_neonatal_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mandatory_investigations_done_during_anc AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mandatory_investigations_done_during_anc,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_neck_assessment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_neck_assessment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.assisted_vaginal_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS assisted_vaginal_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.haematological_disorder AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS haematological_disorder,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cardiac_disease AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cardiac_disease,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.respiratory_diseases AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS respiratory_diseases,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.seizures_epilepsy AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS seizures_epilepsy,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mental_health_illness AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mental_health_illness,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.endocrine_disease AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS endocrine_disease,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thromboembolic_disease AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thromboembolic_disease,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.connective_tissue_disorders AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS connective_tissue_disorders,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hypersensitivity_allergies_and_reactions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hypersensitivity_allergies_and_reactions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.skin_and_mucosal_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS skin_and_mucosal_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.skeletal_abnormalities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS skeletal_abnormalities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_cancer AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_cancer,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reduced_exercise_tolerance AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reduced_exercise_tolerance,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oedema_lower_extremities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oedema_lower_extremities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weakness_or_numbness AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weakness_or_numbness,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.excessive_vomiting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS excessive_vomiting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.heat_or_cold_intolerance AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS heat_or_cold_intolerance,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.previous_pregnancy_history AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS previous_pregnancy_history,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dosage_iron AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dosage_iron,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.frequency_iron AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS frequency_iron,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.duration_iron AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS duration_iron,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dosage_anti_malarial AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dosage_anti_malarial,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.frequency_anti_malarial AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS frequency_anti_malarial,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.duration_anti_malarial AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS duration_anti_malarial,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pregnancy_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pregnancy_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.delivery_date_year AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS delivery_date_year,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_birthweight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_birthweight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.labour_duration_hours AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS labour_duration_hours,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestational_age_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestational_age_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cervical_cancer AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cervical_cancer,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.std_stis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS std_stis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pre_existing_anaemia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pre_existing_anaemia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.other_health_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS other_health_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.when_last_did_she_pass_urine AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS when_last_did_she_pass_urine,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.does_the_woman_have_the_urge_to_push AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS does_the_woman_have_the_urge_to_push,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.is_the_assessment_within AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS is_the_assessment_within,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.health_education_topics AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS health_education_topics,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.itn_provided AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS itn_provided,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_vaccines_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_vaccines_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.urination AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS urination,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gender AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gender,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate_estimated AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate_estimated,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.first_ld_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS first_ld_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_years_at_first_ld_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_years_at_first_ld_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.record_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS record_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.related_person_ids AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS related_person_ids,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.related_relationships AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS related_relationships,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dead AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dead,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.death_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS death_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.arv_number_identifier AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS arv_number_identifier,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_previous_pregnancy_groups AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_previous_pregnancy_groups,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_distinct_previous_pregnancies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_distinct_previous_pregnancies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.latest_previous_delivery_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS latest_previous_delivery_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_pregnancy_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_pregnancy_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_vaginal_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_vaginal_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_delivery_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_delivery_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery_details AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery_details,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_multiple_gestation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_multiple_gestation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_number_of_babies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_number_of_babies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_delivery_date_year AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_delivery_date_year,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_outcome_of_baby_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_outcome_of_baby_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_baby_birthweight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_baby_birthweight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_labour_duration_hours AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_labour_duration_hours,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_gestational_age_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_gestational_age_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_monitoring_rounds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_monitoring_rounds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_gravida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_gravida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_abortions_miscarriages AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_abortions_miscarriages,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_stillbirths AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_stillbirths,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_live_births AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_live_births,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_parity AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_parity,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_chronic_conditions AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_chronic_conditions,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_medications_currently_prescribed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_medications_currently_prescribed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_received_tetanus_doses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_received_tetanus_doses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_tt1date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_tt1date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_tt2date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_tt2date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_gestation_weeks AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_gestation_weeks,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_gestation_age_to_be_used AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_gestation_age_to_be_used,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_lmnp_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_lmnp_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_estimated_date_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_estimated_date_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_estimated_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_estimated_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_number_of_previous_anc_contacts AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_number_of_previous_anc_contacts,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_hiv_test_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_hiv_test_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_art_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_art_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_is_client_on_art AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_is_client_on_art,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anc_pregnancy_outcome AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anc_pregnancy_outcome
    FROM mahis_pivot p
    WHERE p.record_type IN ('baby', 'unknown')
    GROUP BY p.person_id
),

rules AS (
    SELECT 'apgar_score_at_1_minute' AS rule_id, 'ld_del_apgar_score_1_minute' AS dictionary_name, 'APGAR score at 1 minute' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'apgar_score_at_5_minutes' AS rule_id, 'ld_del_apgar_score_5_minutes' AS dictionary_name, 'APGAR score at 5 minutes' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'baby_weight' AS rule_id, 'ld_del_weight' AS dictionary_name, 'Baby weight' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'length' AS rule_id, 'ld_del_height' AS dictionary_name, 'Baby height' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'head_circumference' AS rule_id, 'ld_del_circumference' AS dictionary_name, 'Head circumference' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'time_of_delivery' AS rule_id, 'ld_del_time_delivery' AS dictionary_name, 'Time of delivery' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'date_of_delivery' AS rule_id, 'ld_del_date_delivery' AS dictionary_name, 'Date of delivery' AS label, 'Delivery Details' AS section, 'MANDATORY' AS requirement, '' AS condition_text
),

baby_rule_results AS (
    -- baby_level is read once: every rule result is packed as [applicable, present] in one JSON object per baby
    SELECT person_id, JSON_OBJECT(
        'apgar_score_at_1_minute', JSON_ARRAY(1, CASE WHEN (apgar_score_at_1_minute) IS NOT NULL THEN 1 ELSE 0 END),
        'apgar_score_at_5_minutes', JSON_ARRAY(1, CASE WHEN (apgar_score_at_5_minutes) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_weight', JSON_ARRAY(1, CASE WHEN (COALESCE(weight_grams, current_weight)) IS NOT NULL THEN 1 ELSE 0 END),
        'length', JSON_ARRAY(1, CASE WHEN (length) IS NOT NULL THEN 1 ELSE 0 END),
        'head_circumference', JSON_ARRAY(1, CASE WHEN (head_circumference) IS NOT NULL THEN 1 ELSE 0 END),
        'time_of_delivery', JSON_ARRAY(1, CASE WHEN (time_of_delivery) IS NOT NULL THEN 1 ELSE 0 END),
        'date_of_delivery', JSON_ARRAY(1, CASE WHEN (date_of_delivery) IS NOT NULL THEN 1 ELSE 0 END)
    ) AS j
    FROM baby_level
),

field_status AS (
    -- Unpivot the JSON into one row per baby per rule
    SELECT
        b.person_id,
        k.rule_id,
        r.requirement,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[0]')) AS UNSIGNED) AS applicable,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[1]')) AS UNSIGNED) AS present
    FROM baby_rule_results b
    JOIN JSON_TABLE(JSON_KEYS(b.j), '$[*]' COLUMNS (rule_id VARCHAR(100) PATH '$')) k
    INNER JOIN rules r ON r.rule_id = k.rule_id
),

baby_dq AS (
    -- Per-baby counts of mandatory and conditional fields
    SELECT
        b.person_id,
        SUM(CASE WHEN f.requirement = 'MANDATORY' THEN 1 ELSE 0 END) AS mandatory_fields,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 1 THEN 1 ELSE 0 END) AS mandatory_present,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN 1 ELSE 0 END) AS mandatory_missing,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 THEN 1 ELSE 0 END) AS conditional_required,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 1 THEN 1 ELSE 0 END) AS conditional_present,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN 1 ELSE 0 END) AS conditional_missing,
        GROUP_CONCAT(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_mandatory_fields,
        GROUP_CONCAT(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_conditional_fields
    FROM baby_level b
    INNER JOIN field_status f ON f.person_id = b.person_id
    GROUP BY b.person_id
)

SELECT 'Total babies' AS measure, COUNT(*) AS babies, 100.0 AS pct FROM baby_dq
UNION ALL SELECT 'Babies with ALL mandatory fields present', SUM(mandatory_missing = 0), ROUND(100 * SUM(mandatory_missing = 0) / COUNT(*), 1) FROM baby_dq
UNION ALL SELECT 'Babies with MISSING mandatory fields', SUM(mandatory_missing > 0), ROUND(100 * SUM(mandatory_missing > 0) / COUNT(*), 1) FROM baby_dq
UNION ALL SELECT 'Babies with required conditional fields missing', SUM(conditional_missing > 0), ROUND(100 * SUM(conditional_missing > 0) / COUNT(*), 1) FROM baby_dq
UNION ALL SELECT 'Babies with all mandatory AND all required conditional fields present', SUM(mandatory_missing = 0 AND conditional_missing = 0), ROUND(100 * SUM(mandatory_missing = 0 AND conditional_missing = 0) / COUNT(*), 1) FROM baby_dq
UNION ALL SELECT 'Babies with required conditional fields (any triggered)', SUM(conditional_required > 0), ROUND(100 * SUM(conditional_required > 0) / COUNT(*), 1) FROM baby_dq
UNION ALL SELECT 'Average mandatory completeness (% of mandatory fields present per baby)', COUNT(*), ROUND(AVG(100 * mandatory_present / mandatory_fields), 1) FROM baby_dq
UNION ALL SELECT 'Average required-conditional completeness (% present per baby)', SUM(conditional_required > 0), ROUND(AVG(CASE WHEN conditional_required > 0 THEN 100 * conditional_present / conditional_required END), 1) FROM baby_dq;
